updated_cf = 0
updated_cw = 0
updated_mc = 0

for d in docs:
    did = d["id"]
    if did in CF_FIXES:
        d["summary"] = CF_FIXES[did]
        updated_cf += 1
    elif did in CW_FIXES:
        d["summary"] = CW_FIXES[did]
        updated_cw += 1
    elif did in MC_FIXES:
        d["summary"] = MC_FIXES[did]
        updated_mc += 1

print(f"Applied fixes: CalFresh={updated_cf}, CalWORKs={updated_cw}, Medi-Cal={updated_mc}")

with open(DOCS_PATH, "w") as f:
    json.dump(docs, f, indent=2)

print("Saved updated documents.json.")
